CREATE TABLE sync_preferences(company_id INTEGER NOT NULL REFERENCES companies(id),environment TEXT NOT NULL CHECK(environment IN ('test','production')),represented INTEGER NOT NULL DEFAULT 0 CHECK(represented IN (0,1)),auto_pdf INTEGER NOT NULL DEFAULT 0 CHECK(auto_pdf IN (0,1)),PRIMARY KEY(company_id,environment));
CREATE TABLE expense_book_snapshots(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES companies(id),environment TEXT NOT NULL,date_from TEXT NOT NULL,date_to TEXT NOT NULL,rows_json TEXT NOT NULL,xml_hashes_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
